'use strict';

// MODULES //

var expf = require( '@stdlib/math/base/special/expf' );
var log1pf = require( '@stdlib/math/base/special/log1pf' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );


// MAIN //

/**
* Computes the inverse of a one-parameter Box-Cox transformation for a single-precision floating-point number.
*
* @param {number} y - input value
* @param {number} lambda - power parameter
* @returns {number} inverse of the Box-Cox transformation
*
* @example
* var v = boxcoxinvf( 1.0, 2.5 );
* // returns ~1.6505
*
* @example
* var v = boxcoxinvf( 4.0, 2.5 );
* // returns ~2.6095
*
* @example
* var v = boxcoxinvf( 10.0, 2.5 );
* // returns ~3.6812
*
* @example
* var v = boxcoxinvf( 2.0, 0.0 );
* // returns ~7.3891
*
* @example
* var v = boxcoxinvf( -1.0, 2.5 );
* // returns NaN
*
* @example
* var v = boxcoxinvf( 0.0, -1.0 );
* // returns 1.0
*
* @example
* var v = boxcoxinvf( 1.0, NaN );
* // returns NaN
*
* @example
* var v = boxcoxinvf( NaN, 3.1 );
* // returns NaN
*/
function boxcoxinvf( y, lambda ) {
	y = f32( y );
	lambda = f32( lambda );
	if ( isnanf( y ) || isnanf( lambda ) ) {
		return NaN;
	}
	if ( lambda === 0.0 ) {
		return expf( y );
	}
	return expf( f32( log1pf( f32( lambda*y ) ) / lambda ) );
}


// EXPORTS //

module.exports = boxcoxinvf;
